PROGRAM LubePulse
VAR_INPUT Press AT %I0.0 : BOOL; GuardClosed AT %I0.1 : BOOL; END_VAR
VAR_OUTPUT Pump AT %QX0.0 : BOOL; END_VAR
VAR Shot : TP; Start : BOOL; END_VAR
Start := Press AND GuardClosed;
Shot(IN := Start, PT := T#500ms);
Pump := Shot.Q;
END_PROGRAM

PROGRAM LubePulse
VAR_INPUT Press AT %I0.0 : BOOL; GuardClosed AT %I0.1 : BOOL; END_VAR
VAR_OUTPUT Pump AT %QX0.0 : BOOL; END_VAR
VAR Shot : TP; END_VAR
IF GuardClosed THEN
    Shot(IN := Press, PT := T#500ms);
END_IF;
Pump := Shot.Q;
END_PROGRAM
